 if(["belongsTo","oref"].includes(c)||(f==="purchase"&&k==="extras"&&c==="kind")){redrawRows(k);if(f==="payment"&&k==="allocations")fillRefSelect(`r_allocations_${i}_ref`,val("party"),r.ref)}
 if(f==="product"&&k==="suppliers"&&c==="party"&&!r.cur)r.cur=party(v)?.cur||"RMB";
