function fillRefSelect(id,partyCode,current){const sel=$("#"+id);if(!sel)return;{const m=String(id).match(/^r_allocations_(\d+)_ref$/);const row=m&&S.drawer?.rows?.allocations?.[+m[1]];if(row&&isOtherAlloc(row)){sel.innerHTML=`<option value="${esc(row.ref||"")}">↳ for something else — see below${row.ref?" ("+esc(row.ref)+")":""}</option>`;sel.disabled=true;return}sel.disabled=false}const opts=[];const all=!!S.drawer?.allParties;const mine=x=>all||x===partyCode;const pa=party(partyCode);const tag=x=>all&&x.party&&x.party!==partyCode?` · ${pname(x.party)}`:"";
 live(D.purchases).filter(p=>mine(p.party)&&!["cancelled"].includes(p.status)).sort((a,b)=>a.date<b.date?1:-1).forEach(p=>{const st=poState(p);opts.push([p.no,`${st.outstandingCur>0?"● ":""}${p.no}${p.oldRef?" ("+p.oldRef+")":""}${tag(p)} · ${poDesc(p).slice(0,28)} · ${st.outstandingCur>0?"owes "+fmt(st.outstandingCur,p.cur):st.payLabel}`])});
 live(D.shipments).filter(s=>mine(s.party)||s.paidVia===partyCode).sort((a,b)=>(a.dispatch||a.date||"")<(b.dispatch||b.date||"")?1:-1).forEach(s=>{const paid=paysFor(s.no).reduce((a,x)=>a+allocAmount(x,s.no),0);opts.push([s.no,`${paid<(+s.cost||0)?"● ":""}${s.no}${s.oldRef?" ("+s.oldRef+")":""}${tag(s)} · ${L("mode",s.mode)} · ${fmt(s.cost,s.costCur)}`])});
 live(D.inspections).filter(i=>mine(i.party)).forEach(i=>opts.push([i.no,`${i.no}${tag(i)} · ${i.po} · ${fmt(i.fee,i.cur)}`]));
 live(D.credits).filter(c=>mine(c.party)&&c.status==="open").forEach(c=>opts.push([c.no,`${c.no}${tag(c)} · credit ${fmt(c.amount,c.cur)}`]));
 /* duty / import VAT / UK costs go against the receipt; courier costs against the stock move */
 const dutyParty=["customs","courier"].includes(pa?.type);live(D.receipts).filter(r=>all||r.agent===partyCode||(dutyParty&&(+r.dutyGbp||+r.vatGbp||+r.ukExtraGbp))).sort((a,b)=>(a.date||"")<(b.date||"")?1:-1).slice(0,80).forEach(r=>opts.push([r.no,`${r.no} · receipt ${r.src||""} · duty ${gbp(+r.dutyGbp||0)} · VAT ${gbp(+r.vatGbp||0)}`]));
 live(D.moves).filter(m=>(m.courier&&(all||m.courier===partyCode))).sort((a,b)=>(a.date||"")<(b.date||"")?1:-1).slice(0,80).forEach(m=>opts.push([m.no,`${m.no} · ${L("moveType",m.type)} ${m.qty} ${product(m.sku)?.name||m.sku} → ${locName(m.to)}${m.fbaId?" · "+m.fbaId:""}`]));
 if(current&&!opts.some(o=>o[0]===current))opts.push([current,current+(colOfRef(current)?"":" (not found)")]);
 sel.innerHTML=`<option value="">— general / on account —</option>${optsHtml(opts,current)}${all?"":`<option value="__all">＋ Show other parties' documents…</option>`}`;if(current)sel.value=current}

