/* an AUTO unit price taken from a supplier price in another currency is converted at the order-date rate, with the working shown */
function convertLineUnit(l,i,p){const src=l.uSrc;if(!src)return;const pc=val("cur")||src.cur,dt=val("date")||today();const hint=$("#hint_lines");p=p||product(l.sku);
 if(src.cur===pc){l.u=src.price;if(hint&&hint.dataset.conv===String(i)){hint.textContent="";delete hint.dataset.conv}return}
 const v=convCur(src.price,src.cur,pc,dt);if(v==null){l.u=null;if(hint){hint.textContent=`⚠ ${p?.name||l.sku}: supplier price ${fmt(src.price,src.cur)} cannot be converted — ${noRateMsg(src.cur==="GBP"?pc:src.cur,dt)}`;hint.dataset.conv=String(i)}return}
 l.u=r2(v);if(hint){hint.textContent=`AUTO · ${p?.name||l.sku}: unit ${fmt(src.price,src.cur)} (${pname(src.party)}'s price) → ${fmt(toGbp(src.price,src.cur,dt),"GBP")} at ${num(rateOn(dt,src.cur),5)} → ${fmt(l.u,pc)} at the ${fmtD(dt)} ${pc} rate — check against the PI`;hint.dataset.conv=String(i)}}
