 const sp=poSplit({cur,feePct:val("feePct"),lines:L_,extras:rowsOf("extras"),total:null});const sub=r2(L_.filter(l=>!isOther(l)).reduce((t,l)=>t+(+l.a||0),0));const fee=feeEx?0:r2(sp.fee);const ex=r2(sp.extras+(feeEx?sp.fee:0));const tot=sp.computed;S.drawer.split=sp;updRowCalc("lines");
