/* ================= COUNT ================= */
function initCount(ctx){setv("no",nextNo("moves",ctx.date||today()),true);setv("date",ctx.date||today(),true);setv("loc",ctx.loc||DEF().sellLoc,true);syncCount(true)}
function syncCount(fill){const locId=val("loc");if(fill||locId!==S.drawer.lastLoc){S.drawer.lastLoc=locId;S.drawer.rows.lines=D.products.filter(p=>stockOf(p.sku).byLoc[locId]>0).map(p=>({sku:p.sku,system:stockOf(p.sku).byLoc[locId]||0,counted:null}));redrawRows("lines")}const rows=rowsOf("lines");const diff=rows.filter(r=>r.counted!=null&&r.counted!=="").map(r=>({r,d:(+r.counted)-(+r.system||0)})).filter(x=>x.d);const h=$("#formhint");if(h)h.innerHTML=diff.length?`${diff.length} difference(s): ${diff.map(x=>`${product(x.r.sku)?.name} ${x.d>0?"+":""}${x.d}`).join(" · ")} — each becomes an adjustment with reason "Count difference"`:"Enter the counted packs; blank = not counted"}
function validateCount(o){const errors={},warnings=[];requiredCheck("count",o,errors);(o.lines||[]).forEach(r=>{if(r.counted!=null&&r.counted!==""&&(!Number.isInteger(+r.counted)||+r.counted<0))errors.lines="Counted packs must be whole numbers, 0 or more"});return{errors,warnings}}
async function saveCount(){{const v=validateCount(collect("count"));if(Object.keys(v.errors).length){showErrors(v.errors,v.warnings);return}}const rows=rowsOf("lines").filter(r=>r.sku&&r.counted!=null&&r.counted!=="");const locId=val("loc");const date=val("date");if(!locId){showErrors({loc:"Pick a location"},[]);return}const diffs=rows.map(r=>({sku:r.sku,d:(+r.counted)-(+r.system||0)})).filter(x=>x.d);if(!diffs.length){toast("No differences — nothing to save");S.drawer=null;render();return}
 beginBatch(`Stock count ${locName(locId)}`);for(const x of diffs){const no=nextNo("moves",date);await writeDoc("moves",no,{no,type:"count",sku:x.sku,qty:x.d,from:x.d<0?locId:null,to:x.d>0?locId:null,date,reason:"count_diff",notes:val("notes")||`Count ${fmtD(date)} at ${locName(locId)}`},null,{quiet:true})}await endBatch();S.drawer=null;render();toast(`${diffs.length} adjustment(s) saved`,{undo:true});go("stock")}

/* ================= CREDIT ================= */
/* what a short / damaged receipt is worth in the order currency: (short + damaged) × unit × (1 + fee %) */
function receiptShortfall(rc,poNo){const r=D.receipts.find(x=>x.no===rc);if(!r)return null;const po=D.purchases.find(p=>p.no===(poNo||r.pos?.[0]));if(!po)return null;const sh=D.shipments.find(s=>s.no===r.src);const rows=[];let short=0,dmg=0,amt=0;
 const skus=[...new Set((r.lines||[]).filter(l=>l.po===po.no).map(l=>l.sku))];skus.forEach(sku=>{const pl=(po.lines||[]).find(l=>l.sku===sku);if(!pl)return;const exp=sh?shipLinesExpanded(sh).filter(l=>l.po===po.no&&l.sku===sku).reduce((a,l)=>a+(+l.q||0),0):(+pl.q||0);const got=live(D.receipts).filter(x=>x.src===r.src).reduce((a,x)=>a+(x.lines||[]).filter(l=>l.po===po.no&&l.sku===sku).reduce((b,l)=>b+(+l.q||0),0),0);const sq=Math.max(0,exp-got);const dq=(r.lines||[]).filter(l=>l.po===po.no&&l.sku===sku).reduce((a,l)=>a+(+l.damaged||0),0);const unit=r2((+pl.u||0)*(1+lineFeePct(po,pl)/100));if(!sq&&!dq)return;short+=sq;dmg+=dq;amt+=(sq+dq)*unit;rows.push(`${sq?`${num(sq)} short`:""}${sq&&dq?" + ":""}${dq?`${num(dq)} damaged`:""} × ${fmt(unit,po.cur)}${lineFeePct(po,pl)?` (incl. ${num(lineFeePct(po,pl),1)}% fee)`:""} ${esc(product(sku)?.name||sku)}`)});
 return{po,short,dmg,amount:r2(amt),text:rows.length?`${rows.join(" + ")} = ${fmt(r2(amt),po.cur)}`:""}}
function initCredit(ctx){const e=ctx.edit;if(e){setv("no",e.no);return}setv("no",nextNo("credits"),true);setv("date",ctx.date||today(),true);setv("status","open",true);if(ctx.po){const p=D.purchases.find(x=>x.no===ctx.po);setv("po",ctx.po);if(p){setv("party",p.party);setv("cur",p.cur,true)}}if(ctx.rc){setv("receipt",ctx.rc);const r=D.receipts.find(x=>x.no===ctx.rc);const po=D.purchases.find(p=>p.no===r?.pos?.[0]);if(po){setv("po",po.no);setv("party",po.party);setv("cur",po.cur,true)}const sf=receiptShortfall(ctx.rc,po?.no);if(sf&&sf.amount>0){setv("amount",sf.amount,true);S.drawer.shortQty=sf.short;S.drawer.damagedQty=sf.dmg;setv("reason",sf.short?"short":"damaged",true);const h=$("#formhint");if(h)h.innerHTML=`AUTO · ${sf.text}`}else setv("reason","short",true)}}
function validateCredit(o){const errors={},warnings=[];requiredCheck("credit",o,errors);if(!(o.amount>0))errors.amount="Enter the amount";{const re=rateErr(o.cur,o.date);if(re)errors.cur=re}const po=D.purchases.find(p=>p.no===o.po);if(po&&o.amount>0){const st=poState(po);const a=o.cur===po.cur?+o.amount:convCur(o.amount,o.cur,po.cur,o.date);if(a!=null&&st.total&&a>st.total+0.5)warnings.push(`Credit ${fmt(o.amount,o.cur)} is more than the whole order ${po.no} (${fmt(st.total,po.cur)})`)}return{errors,warnings}}
async function saveCredit(){const o=collect("credit");const{errors,warnings}=validateCredit(o);showErrors(errors,warnings);if(Object.keys(errors).length)return;if(warnings.length&&!S.drawer.ack)return;const old=S.drawer.ctx.edit||{};const no=old.no||val("no")||nextNo("credits",o.date);const d={...old,...o,no};if(S.drawer.shortQty!=null&&!S.drawer.changed.amount){d.shortQty=S.drawer.shortQty;d.damagedQty=S.drawer.damagedQty||0}keepStored("credit",d,old);beginBatch(`${no} saved`);const ok=await writeDoc("credits",no,d,null);if(ok&&o.receipt&&o.receipt!==old.receipt){const r=D.receipts.find(x=>x.no===o.receipt);if(r)await updateDoc("receipts",r.no,{claim:{...(r.claim||{}),status:"credited",credit:no}},`${r.no} claim credited by ${no}`,{quiet:true})}await endBatch();if(ok)finishSave("credits",no,`${no} saved`)}

/* ================= PRODUCT ================= */
function initProduct(ctx){const e=ctx.edit;if(e){/* the SKU is the product's key on every order, shipment, receipt and move: it cannot be retyped — "Merge into…" re-points everything */const sk=$("#f_sku");if(sk){sk.readOnly=true;sk.setAttribute("aria-readonly","true");const w=$("#fw_sku");if(w&&!w.querySelector(".skuhint"))w.insertAdjacentHTML("beforeend",`<span class="hint skuhint">The SKU cannot be changed here — use the product's More › Merge into… to move everything to another SKU</span>`)}setv("ean",(e.ean||[]).join(", "));redrawRows("suppliers");redrawRows("listings");redrawRows("components");syncProduct();return}setv("status","active",true);setv("packOf",1,true);setv("unit","pack",true);setv("isNew",true,true);setv("cycleDays",DEF().cycleDays,true);setv("safetyDays",DEF().safetyDays,true);setv("dutyPct",FEES().dutyDefaultPct,true);setv("goodsType","gen",true);setv("defaultMode",DEF().mode,true);if(ctx.name)setv("name",ctx.name);if(last("product","brand"))setv("brand",last("product","brand"),true);syncProduct()}
function syncProduct(){const brand=val("brand"),cat=val("category");const c=item("category",cat);const top=c?.parent?item("category",c.parent):c;if(!S.drawer.ctx.edit){if(!touched("sku")&&brand&&cat)setv("sku",skuFor(brand,cat),true);if(!touched("name")&&cat){const pk=+val("packOf")||1;setv("name",`${top?.label||""}${c?.parent?" "+c.label:""}${pk>1?" pack of "+pk:""}`.trim(),true)}}
 if(top){if(!touched("hs")&&top.hs)setv("hs",top.hs,true);if(!touched("dutyPct")&&top.duty!=null)setv("dutyPct",top.duty,true);if(!touched("goodsType")&&top.goodsType)setv("goodsType",top.goodsType,true)}
 const sku=(val("sku")||"").trim().toUpperCase();const h=$("#formhint");if(h){const ex=sku&&product(sku)&&!S.drawer.ctx.edit;const bad=sku&&!/^[A-Z0-9]+(-[A-Z0-9]+)+$/.test(sku);h.innerHTML=ex?`<span class="err">SKU ${sku} already exists</span>`:bad?`<span class="err">SKU should look like WAL-TB-GRY-01 (letters/numbers and dashes)</span>`:sku?`SKU ${sku}`:""}}
function validateProduct(o){const errors={},warnings=[];requiredCheck("product",o,errors);const sku=(o.sku||"").trim().toUpperCase();if(sku&&!/^[A-Z0-9]+(-[A-Z0-9]+)+$/.test(sku))errors.sku="Use letters/numbers and dashes, e.g. WAL-TB-GRY-01";if(sku&&!S.drawer.ctx.edit&&product(sku))errors.sku="This SKU already exists";if(S.drawer.ctx.edit&&sku!==String(S.drawer.ctx.edit.sku||"").toUpperCase())errors.sku=`The SKU cannot be changed (it is on orders, shipments and stock) — use More › Merge into… on ${S.drawer.ctx.edit.sku}`;if(!(+o.packOf>=1)||!Number.isInteger(+o.packOf))errors.packOf="A whole number, at least 1";
 ["pk","ctn"].forEach(k=>{const d=o[k]||{};if(["L","W","H","kg"].some(x=>d[x]!=null&&d[x]!==""&&+d[x]<0))errors[k]="Sizes and weight cannot be negative"});if(o.perCtn!=null&&o.perCtn!==""&&(!Number.isInteger(+o.perCtn)||+o.perCtn<=0))errors.perCtn="Packs per carton must be a whole number above 0";["cycleDays","safetyDays","velocityOverride","sellGbp","dutyPct"].forEach(k=>{if(o[k]!=null&&o[k]!==""&&+o[k]<0)errors[k]="Cannot be negative"});
 const dup=D.products.find(p=>p.sku!==sku&&norm(p.name)===norm(o.name)&&(+p.packOf||1)===(+o.packOf||1));if(dup&&!S.drawer.ctx.edit)warnings.push(`Same name as ${dup.sku} — is it the same product?`);
 const eans=(o.ean||"").split(/[,\s]+/).filter(Boolean);eans.forEach(e=>{const d=D.products.find(p=>p.sku!==sku&&(p.ean||[]).includes(e));if(d)errors.ean=`Barcode ${e} is already on ${d.sku}`;if(!/^\d{8,14}$/.test(e))warnings.push(`Barcode ${e} is not 8–14 digits`)});
 const c=o.ctn||{};if((c.L||c.W||c.H)&&!(c.L&&c.W&&c.H))errors.ctn="Enter all three carton sides";if((c.L||c.W||c.H||c.kg)&&(o.perCtn==null||o.perCtn===""))errors.perCtn="Packs per carton needed with carton size";return{errors,warnings}}
async function saveProduct(){const o=collect("product");const{errors,warnings}=validateProduct(o);showErrors(errors,warnings);if(Object.keys(errors).length)return;if(warnings.length&&!S.drawer.ack)return;const old=S.drawer.ctx.edit||{};const sku=(old.sku||o.sku).trim().toUpperCase();
 const d={...old,...o,sku,id:sku,ean:(o.ean||"").split(/[,\s]+/).filter(Boolean),suppliers:o.suppliers.filter(s=>s.party).map(s=>({...s,price:+s.price||null,moq:+s.moq||null,cur:s.cur||party(s.party)?.cur||"RMB"})).sort((a,b)=>(a.validFrom||"")<(b.validFrom||"")?1:-1),listings:o.listings.filter(l=>l.marketplace),components:o.components.filter(c=>c.sku),priceHistory:old.priceHistory||[]};keepStored("product",d,old);
 remember("product","brand",d.brand);const ok=await writeDoc("products",sku,d,null);if(ok)finishSave("products",sku,`${sku} saved`)}

