/* ---------- paint: field / cell status, row messages, panel, Save badge ---------- */
function faSuggHtml(x){return(x.sugg||[]).map((s,j)=>`<button type="button" class="btn sm fa-use${s.open?" fa-open":""}" data-fa="use" data-id="${esc(x.id)}" data-s="${j}" title="${s.open?"Opens another record":s.safe?"Safe — included in Fix all suggested":"Check before using"}">${esc(s.label)}</button>`).join("")}
