 const acts=(n+pend.length?`<button type="button" class="btn sm" data-fa="prev" aria-label="Previous issue (Alt+↑)" title="Previous issue (Alt+↑)">‹</button><button type="button" class="btn sm" data-fa="next" aria-label="Next issue (Alt+↓)" title="Next issue (Alt+↓)">Next ›</button>`:"")+(safeN?`<button type="button" class="btn sm fa-fix" data-fa="fixall" title="Applies only the safe suggestions, then checks again">Fix all suggested (${safeN})</button>`:"")+(ackOk?`<button type="button" class="btn sm" data-act="ack">Save anyway</button>`:"")+(fa.issues.length?`<button type="button" class="btn sm fa-tog" data-fa="toggle" aria-expanded="${fa.open}" aria-controls="fa-body" aria-label="${fa.open?"Hide":"Show"} the list">${fa.open?"▴":"▾"}</button>`:"");
