/* ---------- navigation & actions ---------- */
function faNavList(){const fa=faState();if(!fa)return[];const r=fa.issues.filter(x=>x.rev);return r.length?r:fa.issues}
function faGoto(id){const fa=faState();if(!fa)return;const x=fa.issues.find(y=>y.id===id);if(!x)return;fa.idx=faNavList().indexOf(x);const el=faEl(x);if(!el)return;const tgt=el.matches("input,select,textarea,button")?el:el.querySelector("input:not([readonly]),select,textarea,button")||el;
 try{tgt.scrollIntoView({block:"center",behavior:"smooth"})}catch(_){tgt.scrollIntoView()}try{tgt.focus({preventScroll:true})}catch(_){tgt.focus()}fa.lastFocus=tgt.id||null;tgt.classList.remove("fa-flash");void tgt.offsetWidth;tgt.classList.add("fa-flash");setTimeout(()=>tgt.classList.remove("fa-flash"),1300)}
function faNext(dir){const fa=faState();if(!fa)return;const l=faNavList();if(!l.length){toast("No issues — ready to save");return}fa.idx=((fa.idx<0&&dir<0?0:fa.idx)+dir+l.length)%l.length;faGoto(l[fa.idx].id)}
function faFirst(){const fa=faState();if(!fa)return;const x=fa.issues.find(y=>y.rev&&y.level==="error")||fa.issues.find(y=>y.rev);if(x)faGoto(x.id)}
function faUse(id,j){const fa=faState();if(!fa)return;const x=fa.issues.find(y=>y.id===id);const s=x?.sugg?.[j];if(!s)return;try{s.apply()}catch(e){console.warn("suggestion",e);toast("Could not apply that suggestion");return}if(!s.open&&S.drawer?.fa===fa){const el=faEl(x);if(el&&el.matches?.("input,select,textarea")){try{el.focus({preventScroll:true})}catch(_){}}faSchedule(0)}}
function faFixAll(){const fa=faState();if(!fa)return;let n=0;const done=new Set();for(let pass=0;pass<6;pass++){faRun();const groups=new Set();const todo=[];fa.issues.forEach(x=>{const g=x.rows!=null?x.rows:x.field||"";(x.sugg||[]).forEach(s=>{const key=x.id+"|"+s.label;if(!s.safe||done.has(key)||groups.has(g))return;groups.add(g);done.add(key);todo.push(s)})});if(!todo.length)break;todo.forEach(s=>{try{s.apply();n++}catch(e){console.warn("fix all",e)}});if(S.drawer?.fa!==fa)return}
 clearTimeout(faT);faRun();toast(n?`${n} suggestion${n>1?"s":""} applied (marked AUTO) — check them before saving`:"Nothing safe to apply automatically")}
function faReturnFocus(){const fa=faState();const el=(fa?.lastFocus&&document.getElementById(fa.lastFocus))||$(".drawer .form input:not([readonly]),.drawer .form select");el?.focus()}
function faVisit(t){const fa=faState();if(!fa)return;if(t.dataset?.row!==undefined){fa.visited[`${t.dataset.row}|${t.dataset.i}|${t.dataset.k}`]=true;fa.visited["rows:"+t.dataset.row]=true;fa.lastFocus=t.id;return}if(t.id?.startsWith("f_")){const k=t.id.slice(2).replace(/_(L|W|H|kg)$/,"");fa.visited[k]=true;fa.lastFocus=t.id}}
function faNoteInput(t){const fa=faState();if(!fa)return;if(t.dataset?.row!==undefined){const rk=t.dataset.row+"|"+t.dataset.i;fa.rowTouched[rk]=true;delete fa.autoCells[rk+"|"+t.dataset.k]}}
function faEnsureCss(){if(document.getElementById("facss"))return;const s=document.createElement("style");s.id="facss";s.textContent=`
.fa{position:sticky;top:-16px;z-index:4;margin:-16px -16px 0;padding:8px 16px;background:var(--panel);border-bottom:1px solid var(--line);box-shadow:0 2px 6px rgba(0,0,0,.05)}
.fa-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;min-width:0}
.fa-bar>.fa-i{font-size:15px}
.fa-sum{font-weight:600;font-size:13px;flex:1 1 140px;min-width:0}
.fa.e .fa-sum,.fa.e .fa-bar>.fa-i{color:var(--bad)}.fa.w .fa-sum,.fa.w .fa-bar>.fa-i{color:var(--warn)}.fa.ok .fa-sum,.fa.ok .fa-bar>.fa-i{color:var(--ok)}.fa.p .fa-sum,.fa.p .fa-bar>.fa-i{color:var(--muted)}
.fa-acts{display:flex;gap:6px;flex-wrap:wrap}
.fa-tog{display:none}
#fa-body{display:block}
.fa-list{list-style:none;margin:6px 0 0;padding:0;max-height:34vh;overflow:auto;display:flex;flex-direction:column;gap:2px}
.fa-list li{display:flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:12.5px;min-width:0}
.fa-go{border:0;background:transparent;text-align:left;padding:4px 6px;border-radius:6px;flex:1 1 220px;min-width:0;color:var(--fg);font:inherit;cursor:pointer;overflow-wrap:anywhere}
.fa-go:hover,.fa-go:focus-visible{background:var(--soft)}
.fa-list li.pend .fa-go{color:var(--muted)}
.fa-i{display:inline-block;min-width:1.1em;text-align:center;font-weight:700}
.fa-i.error{color:var(--bad)}.fa-i.warn{color:var(--warn)}.fa-i.pend{color:var(--muted)}.fa-i.ok{color:var(--ok)}
.btn.sm.fa-use{padding:3px 8px;font-size:12px;background:var(--accent-soft);border-color:var(--accent);color:var(--fg);white-space:normal;text-align:left;max-width:100%}
.btn.sm.fa-use.fa-open{background:var(--panel);border-color:var(--line)}
.fa-todo{font-size:12px;color:var(--muted);margin-top:4px;display:flex;flex-wrap:wrap;gap:4px;align-items:center}
.fa-chip{border:1px dashed var(--line);background:transparent;border-radius:999px;padding:2px 8px;font-size:12px;color:var(--muted);cursor:pointer}
.f .err:empty{display:none}
.f .err{display:flex;flex-direction:column;gap:3px}
.fa-line{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px;font-size:12px;overflow-wrap:anywhere;min-width:0;color:var(--bad)}
.fa-line .fa-t{flex:1 1 160px;min-width:0}
.fa-line.warn{color:var(--warn)}.fa-line.pend{color:var(--muted)}
.fa-ic{margin-left:6px;font-weight:700}.fa-ic.ok{color:var(--ok)}.fa-ic.error{color:var(--bad)}.fa-ic.warn{color:var(--warn)}.fa-ic.pend{color:var(--muted)}
.f.fa-w input,.f.fa-w select,.f.fa-w textarea{border-color:var(--warn)}
.f.fa-p input,.f.fa-p select{border-style:dashed}
.ln .fa-e{border-color:var(--bad)!important;background:var(--bad-bg)}
.ln .fa-w{border-color:var(--warn)!important}
.ln .fa-p{border-style:dashed!important}
.ln .fa-ok{box-shadow:inset 0 -2px 0 var(--ok)}
.ln .fa-auto{box-shadow:inset 0 0 0 1px var(--info)}
.fa-rowmsg{margin:-2px 0 8px;display:flex;flex-direction:column;gap:3px;min-width:0}
.fa-flash{animation:faflash 1.3s ease-out}
@keyframes faflash{0%{box-shadow:0 0 0 4px var(--warn)}100%{box-shadow:0 0 0 0 transparent}}
.df .btn.pri.fa-has{background:var(--bad);border-color:var(--bad)}
.fa-short{display:none}
@media (max-width:600px){.fa-list,.fa-todo{display:none}.fa.open .fa-list,.fa.open .fa-todo{display:flex}.fa-long{display:none}.fa-short{display:inline}.fa-tog{display:inline-flex}.fa:not(.open) .fa-fix,.fa:not(.open) [data-fa="prev"]{display:none}.fa-sum{flex:1 1 60px}}
@media (prefers-reduced-motion:reduce){.fa-flash{animation:none;outline:3px solid var(--warn)}}`;document.head.appendChild(s)}
